import copy
import datetime
import json
import pprint
import re
from robot.api import logger as r_logger
from ta_pcmd.submodule_ute_common_abstract_core.message import Message, KeyFindingDict, NotFoundKey
from ta_pcmd.json_tshark_pcmd_source import JsonTsharkPCMDSource, TSHARK_INTERFACE
from ta_pcmd.asn_definitions.extract_record_from_standard import get_pcmd_protocol_data
from ta_pcmd.logger_config import configure_logger, configure_raw_message_logger
from ta_pcmd.py3_string import py3_string
try:
    from asn1PERser import decode as asn1PERser_decode
    from ta_pcmd.asn_definitions.TraceProtocol_nsetapx import DuVendorExtensionRecordDataType,\
        CuVendorExtensionRecordDataType,\
        CuUpVendorExtensionRecordDataType
    from ta_pcmd.asn_definitions.TraceProtocol_nsetap import VendorExtensionRecordData
except Exception as e:
    message = 'Could not import: asn1PERser due to exception: {}'.format(e)
    try:
        r_logger.warn(message)
    except Exception:
        print(message)
    asn1PERser_decode = None


PCMD_MESSAGE_NAME_ID = {'4G': {'StartSession': '0',
                               'StopSession': '1',
                               'StartRecordingSession': '2',
                               'StopRecordingSession': '3',
                               'Report': '4',
                               'IsAlive': '5',
                               'Configure': '6'},
                        '5G': {'Configure': '0',
                               'IsAlive': '1',
                               'StartSession': '2',
                               'StopSession': '3',
                               'StartRecordingSession': '4',
                               'StopRecordingSession': '5',
                               'Report': '6'}}

USE_ASN_MESSAGE_TYPE_NAME = True
FAIL_TEST_ON_NOT_DECODED_RECORDS = False


class PcmdCollector(object):
    def __init__(self, ip, port, technology='4G', asn1per_decoding=False, tshark_interface=TSHARK_INTERFACE):
        self.ip = ip
        self.port = port
        self.logger = configure_logger('ta_pcmd.pcdm_collector_{}_{}'.format(self.ip, self.port))
        self.trace_id_logger = configure_logger('ta_pcmd.pcdm_collector_{}_{}.traceIds'.format(self.ip, self.port))
        self.trace_id_logger.info('Processing of records start after start_collecting_pcmd* keyword is called')
        self.asn_decoded_logger = configure_raw_message_logger('asn_decoded_{}_{}'.format(self.ip, self.port))
        self.file_logger = configure_raw_message_logger('pcmd_records_{}_{}_{}'
                                                        .format(self.ip, self.port,
                                                                datetime.datetime.today().strftime('%Y%m%d_%H%M%S')))
        self.pcmd_data_source = JsonTsharkPCMDSource(ip=ip, port=port, callback=self.process_pcmd,
                                                     technology=technology,
                                                     tshark_interface=tshark_interface)
        self.pcmd_message_id_name = {id: name for name, id in PCMD_MESSAGE_NAME_ID[technology].items()}
        self.pcmd_message_name_id = PCMD_MESSAGE_NAME_ID[technology]
        self.technology = technology
        self.asn1per_decoding = asn1per_decoding
        self.asn1_decoder = None
        self.asn1_supported_types = None
        self.asn1_supported_types_names = None
        self.asn1_wrongly_decoded_messages = []
        if self.asn1per_decoding is True and asn1PERser_decode is not None:
            self.asn1_decoder = asn1PERser_decode
            if self.technology == '5G':
                self.asn1_supported_types = [DuVendorExtensionRecordDataType, CuVendorExtensionRecordDataType, CuUpVendorExtensionRecordDataType]
            else:
                self.asn1_supported_types = [VendorExtensionRecordData]
            self.asn1_supported_types_names = [class_name.__name__ for class_name in self.asn1_supported_types]
            self.validate_implementation_against_standard()
            self.asn1_record_names = get_pcmd_protocol_data(self.technology, flat=False)
            self.asn1_supported_record_name_to_type = self._get_record_name_to_type_structure()
            self.asn1_supported_record_type_to_name = self._get_record_type_to_name_structure()
        self.is_started = False
        self.pcmd_messages = []
        self.registered_callbacks = {}
        self.trace_ids = []
        self.no_trace_ids_in_pcmd_message = None

    def _get_record_name_to_type_structure(self):
        asn1_supported_record_name_to_type = {}
        for vendor_name in self.asn1_record_names:
            asn1_supported_record_name_to_type[vendor_name] = {}
            for item in self.asn1_record_names[vendor_name]:
                asn1_supported_record_name_to_type[vendor_name][item['record_visible_name']] = item['record_type_name']
        return asn1_supported_record_name_to_type

    def _get_record_type_to_name_structure(self):
        asn1_supported_record_type_to_name = {}
        for vendor_name in self.asn1_record_names:
            asn1_supported_record_type_to_name[vendor_name] = {}
            for item in self.asn1_record_names[vendor_name]:
                asn1_supported_record_type_to_name[vendor_name][item['record_type_name']] = item['record_visible_name']
        return asn1_supported_record_type_to_name

    def validate_implementation_against_standard(self):
        """
        Check if all classes implemented as in standard
        :return:
        """
        vendor_payloads = get_pcmd_protocol_data(self.technology, flat=False).keys()
        if sorted(vendor_payloads) != sorted(self.asn1_supported_types_names):
            self.stop()
            raise Exception('Not all classes implemented. Standard: \n{}, implemented: \n{}'
                            .format(vendor_payloads, self.asn1_supported_types_names))

    def _on_no_trace_id_in_single_collector(self):
        if len(self.pcmd_messages) and self.no_trace_ids_in_pcmd_message is not None:
            r_logger.warn('Not found trace id in pcmd collector: {}:{}\n'
                          'Follow the ta_pcmd.pcdm_collector_{}_{}.log'
                          .format(self.ip, self.port, self.ip, self.port))

    def start_collecting(self):
        ''' to be added '''
        self.is_started = True

    def stop_collecting(self):
        ''' to be added '''
        self._on_no_trace_id_in_single_collector()
        self.is_started = False

    def get_pcmd_messages(self):
        ''' to be added '''
        self._on_no_trace_id_in_single_collector()
        return self.pcmd_messages

    def get_pcmd_trace_ids(self):
        self._on_no_trace_id_in_single_collector()
        return self.trace_ids

    def get_pcmd_messages_per_record_name(self):
        '''
        returns dict as:
        {'recordName': [record1, record2],
        ...
        }
        '''
        assert self.asn1per_decoding is True, 'asn1per_decoding must be enabled'
        records_per_name = {}
        records_per_arrival_time = []
        pcmd_messages_snapshot = copy.deepcopy(self.pcmd_messages)
        for record in pcmd_messages_snapshot:
            if hasattr(record, 'asn1per_record_name') and record.asn1per_record_name is not None:
                records_per_arrival_time.append(record)
                record_list = records_per_name.setdefault(record.asn1per_record_name, [])
                record_list.append(record)
        print('Collected record types by order:\n{}'
              .format([rec.asn1per_record_name for rec in records_per_arrival_time]))
        print('Collected record types:\n{}'
              .format(pprint.pformat(dict((key, len(records_per_name[key])) for key in records_per_name))))
        return records_per_name

    def clear_collected_messages(self):
        ''' to be added '''
        self.pcmd_messages = []

    def stop(self):
        ''' to be added '''
        self.pcmd_data_source.stop()
        self.logger.debug('PCMD collector stopped.')
        if len(self.asn1_wrongly_decoded_messages):
            message = 'During PCMD message collection ' \
                      '{} records could not be decoded\nCarefully investigate asn_decoded_pcmd.log!!'\
                .format(len(self.asn1_wrongly_decoded_messages))
            if FAIL_TEST_ON_NOT_DECODED_RECORDS is False:
                r_logger.warn(message)
            else:
                raise Exception(message)

    def register_callback(self, name, func):
        '''
        to be added
        '''
        self.registered_callbacks[name] = func

    def remove_callback(self, name):
        '''
        to be added
        '''
        self.registered_callbacks = dict((c_name, self.registered_callbacks[c_name])
                                         for c_name in self.registered_callbacks if c_name != name)

    def _get_nsetap_version(self):
        return 'nsetap' if self.technology == '4G' else 'nsetapx'

    def _get_record_name_or_type(self, asn1per_vendor_payload_type, user_used_name):
        if USE_ASN_MESSAGE_TYPE_NAME is True:
            # user_used_name is record type
            return self.asn1_supported_record_type_to_name[asn1per_vendor_payload_type][user_used_name]
        else:
            # user_used_name is record name
            return self.asn1_supported_record_name_to_type[asn1per_vendor_payload_type][user_used_name]

    def decode_trace_id(self, pcmd_message):
        trace_ids = []
        try:
            trace_ids = pcmd_message.get_all_values_by_key('{}.traceId'.format(self._get_nsetap_version()))
            trace_ids = [str(int(re.sub(r':', r'', py3_string(tr_id)), 16)) for tr_id in trace_ids]
            pcmd_message.traceId = copy.deepcopy(trace_ids)
            self.trace_id_logger.debug('Found TraceIds: {} in message: {}'.format(trace_ids, pcmd_message))

        except NotFoundKey:
            self.trace_id_logger.debug('Not able to find TraceId for vendor record: {}'.format(pcmd_message))
            self.no_trace_ids_in_pcmd_message = 'No TraceId detected for some records, check latest: ' \
                                                'pcmd_records_{}_{}*.log'.format(self.ip, self.port)
        except Exception as e:
            self.trace_id_logger.debug(
                'Other exception during decoding of traceID in message: {} occurred:\n{}'
                .format(pcmd_message, e))
        if len(trace_ids):
            for trace_id in trace_ids:
                if trace_id not in self.trace_ids:
                    self.trace_ids.append(trace_id)
                    self.trace_id_logger.debug('Added TraceId:{} to PCMD collector database'.format(trace_id))

    def decode_from_asn_bytes(self, original_pcmd_message):
        ''' to be added '''
        if self.asn1per_decoding is False:
            self.logger.debug('Returning original pcmd message as asn1per decoding is disabled')
            return [original_pcmd_message]
        vendor_data_records = []
        pcmd_messages = []
        vendor_data_records, pcmd_messages = \
            self._extract_vendor_record_from_original_pcmd_message(original_pcmd_message,
                                                                   pcmd_messages, vendor_data_records)
        if len(vendor_data_records) != len(pcmd_messages):
            self.logger.warn('Sth is wrong with decoding in record, skipping it'
                             ':\n{}'.format(pprint.pformat(original_pcmd_message)))
            self.logger.debug('Returning original pcmd message as sth went wrong while getting vendor extensions')
            return [original_pcmd_message]
        for index, vendor_data in enumerate(vendor_data_records):
            (pcmd_messages[index].asn1per_vendor_payload_type,
             pcmd_messages[index].asn1per_record_name,
             pcmd_messages[index].asn1per_decoded) = self._decode_from_asn1per(vendor_data)
            if pcmd_messages[index].asn1per_decoded is not None:
                self.asn_decoded_logger.debug('Decoded {}:{} ({}) record:\n{}\n'
                                              .format(pcmd_messages[index].asn1per_vendor_payload_type,
                                                      pcmd_messages[index].asn1per_record_name,
                                                      self._get_record_name_or_type(
                                                          pcmd_messages[index].asn1per_vendor_payload_type,
                                                          pcmd_messages[index].asn1per_record_name),
                                                      json.dumps(pcmd_messages[index].asn1per_decoded, indent=4)))
            else:
                self.asn_decoded_logger.debug('Could not decode PCMD record:\n{}\n'
                                              .format(pprint.pformat(vendor_data)))
                self.asn1_wrongly_decoded_messages.append(vendor_data)
        self.logger.debug('Returning extracted (multiplied if needed) pcmd messages')
        return pcmd_messages

    def _extract_vendor_record_from_original_pcmd_message(self,
                                                          original_pcmd_message,
                                                          pcmd_messages,
                                                          vendor_data_records):
        try:
            vendor_data_records = original_pcmd_message.get_all_values_by_key('{}.vendorExtensionData_element'
                                                                              .format(self._get_nsetap_version()))
            if len(vendor_data_records) > 1:
                self.logger.debug('Single pcmd message containing multiple pcmd records: {}'
                                  .format(len(vendor_data_records)))
            for x in range(0, len(vendor_data_records)):
                pcmd_messages.append(copy.deepcopy(original_pcmd_message))
        except NotFoundKey:
            pass
        return vendor_data_records, pcmd_messages

    def _map_record_type_to_visible_name(self, record_type):
        return self.asn1_supported_record_type_to_name[record_type]

    def _decode_from_asn1per(self, vendor_record):
        payload_field_name = '{}.ver_Payload'.format(self._get_nsetap_version())
        payload_tree_content = '{}.ver_Payload_tree'.format(self._get_nsetap_version())
        if payload_field_name in vendor_record and payload_tree_content in vendor_record:
            asn_data_hex_str = vendor_record.get_value_by_unique_key(payload_field_name)
            asn_data_bytes = self._convert_to_bytes(asn_data_hex_str)
            asn_vendor_payload_type = self._get_asn_vendor_record_type(payload_tree_content, vendor_record)
            if asn_vendor_payload_type is not None:
                try:
                    asn1_spec_class = self._get_vendor_payload_type_class(asn_vendor_payload_type)
                    decoded = self.asn1_decoder(asn1Spec=asn1_spec_class(),
                                                per_stream=asn_data_bytes)
                    decoded_dict = KeyFindingDict(decoded.to_dict())
                    record_type_name = self._get_record_type_name(asn_vendor_payload_type, decoded_dict)
                    user_used_record_naming = record_type_name \
                        if USE_ASN_MESSAGE_TYPE_NAME is True else\
                        self._map_record_type_to_visible_name[record_type_name]
                    return asn_vendor_payload_type, user_used_record_naming, decoded_dict
                except Exception:
                    return None, None, None
            else:
                return None, None, None
        else:
            return None, None, None

    def _get_vendor_payload_type_class(self, asn_vendor_payload_type):
        if asn_vendor_payload_type in self.asn1_supported_types_names:
            return self.asn1_supported_types[self.asn1_supported_types_names.index(asn_vendor_payload_type)]
        else:
            self.file_logger.error('AsnVendorPayload: Could not find class for: {}'.format(asn_vendor_payload_type))
            return None

    def _convert_to_bytes(self, asn_data_hex_str):
        return bytearray.fromhex(re.sub(":", '', asn_data_hex_str))

    @property
    def record_names_for_validation(self):
        if USE_ASN_MESSAGE_TYPE_NAME is True:
            flat_record_names = list(set([item
                                          for vendor in self.asn1_supported_record_type_to_name
                                          for item in self.asn1_supported_record_type_to_name[vendor]]))
            return flat_record_names
        else:

            flat_record_names = list(set([item
                                          for vendor in self.asn1_supported_record_name_to_type
                                          for item in self.asn1_supported_record_name_to_type[vendor]]))
            return flat_record_names

    def decoded_name_to_record_type(self, asn_vendor_payload_type, decoded_name):
        if decoded_name not in self.asn1_supported_record_name_to_type[asn_vendor_payload_type]:
            self.asn_decoded_logger.error(
                'AsnRecordName: Name: {} not found in supported names: \n{}'
                .format(decoded_name, self.asn1_supported_record_name_to_type[asn_vendor_payload_type].keys()))
            return None
        else:
            return self.asn1_supported_record_name_to_type[asn_vendor_payload_type][decoded_name]

    def is_record_name_supported(self, record_name):
        """
        Checks if record name supported in current implemented standard
        :param record_name:
        :return:
        """
        return True if record_name in self.record_names_for_validation else False

    def _get_record_type_name(self, asn_vendor_payload_type, decoded_record_dict):
        if len(decoded_record_dict) == 1:
            record_decoded_name = list(decoded_record_dict.keys())[0]
            return self.decoded_name_to_record_type(asn_vendor_payload_type, record_decoded_name)
        self.asn_decoded_logger.error('AsnRecordName: Could not find record in keys: {}'
                                      .format(list(decoded_record_dict.keys())))
        return None

    def _get_asn_vendor_record_type(self, tree_content, vendor_record):
        tree_keys = list(vendor_record.get_value_by_unique_key(tree_content).keys())
        for record_type in self.asn1_supported_types_names:
            vendor_field_name = "{}.{}".format(self._get_nsetap_version(), record_type)
            for key in tree_keys:
                if vendor_field_name == key:
                    return record_type
        return None

    def process_pcmd(self, pcmd_message):
        ''' to be added '''
        self.file_logger.debug("\n{}\n".format(pcmd_message) + pprint.pformat(pcmd_message) + "\n")
        if pcmd_message[self.field('TraceMessage')] != self.pcmd_message_name_id['Report']:
            self.logger.debug("Received PCMD message type: '{}'. Ignoring..."
                              .format(self.pcmd_message_id_name[pcmd_message[self.field('TraceMessage')]]))
            return
        self.logger.debug("Received PCMD message type: '{}'"
                          .format(self.pcmd_message_id_name[pcmd_message[self.field('TraceMessage')]]))
        pcmd_message = Message(pcmd_message, {'ip': str(self.ip),
                                              'port': str(self.port),
                                              'traceId': None,
                                              'asn1per_record_name': None,
                                              'asn1per_vendor_payload_type': None,
                                              'asn1per_decoded': None})
        self.process_message(pcmd_message)

    def process_message(self, original_pcmd_message):
        ''' Note that pcmd message can be bundled message, carrying multiple (even the same type) pcmd records.
        In the case single pcmd_message object will be mutlplied so that each object contains single vendor_record,
        as in legacy case. Still the pcmd_message object in json format will contain all fields as captured on
        tce interface, only asn_decoded unique'''
        if self.is_started:
            self.decode_trace_id(original_pcmd_message)
            extracted_pcmd_messages = self.decode_from_asn_bytes(original_pcmd_message)
            self.pcmd_messages.extend(extracted_pcmd_messages)
            for pcmd_message in extracted_pcmd_messages:
                for callback in self.registered_callbacks:
                    try:
                        self.registered_callbacks[callback](pcmd_message)
                    except Exception as e:
                        self.file_logger.warn('CollectorCallback: Callback: {} failed with: {}'.format(callback, e))

    def field(self, field_name):
        ''' to be added '''
        return '{}.{}'.format(self.pcmd_data_source.protocol, field_name)
